#include <stdio.h>

int main(void) {
    int 工资 = 3000, 房租 = 3500;
    int 剩余 = 工资 - 房租;
    if (剩余 >= 0) {
        printf("付完房租还能剩%d元\n", 剩余);
    } else {
        printf("付完房租还差%d元\n", -剩余);
    }
    return 0;
}

#include <stdio.h>

static void 付完房租还能剩(int 工资, int 房租, int 饭钱) {
    int 缺口 = 房租 + 饭钱 - 工资;
    puts("【月底结算小剧场】");
    printf("工资：%d 元\n", 工资);
    printf("房租：%d 元\n", 房租);
    printf("饭钱：%d 元\n", 饭钱);
    if (缺口 > 0) {
        printf("付完房租还能剩？剩个寂寞，还倒欠 %d 元。\n", 缺口);
        puts("钱包：我先去天台吹吹风。");
        puts("房东：谢谢你的工资，它已经不认识你了。");
    } else {
        printf("付完房租还能剩 %d 元，勉强够买杯奶茶。\n", -缺口);
    }
}

int main(void) {
    int 工资 = 3000, 房租 = 3500;
    付完房租还能剩(工资, 房租, 800);
    return 0;
}

#include <stdio.h>

/* 苹果分配小剧场：
   苹果=3，人数=2，平分后每人1个，剩1个。
   剩下的苹果被拟人化为“仲裁苹果”，它拒绝被切开，
   于是大家决定把它供起来，明天再议。 */

static void 平分(int 苹果, int 人数) {
    int 每人 = 苹果 / 人数;
    int 剩余 = 苹果 % 人数;
    printf("🍎 苹果总数：%d\n", 苹果);
    printf("👥 人数：%d\n", 人数);
    printf("➗ 平分结果：每人 %d 个苹果\n", 每人);
    if (剩余 == 0) {
        printf("✅ 刚好分完，皆大欢喜。\n");
    } else {
        printf("⚠️  剩下 %d 个苹果，无法继续平分。\n", 剩余);
        printf("🍎 剩下的苹果发言：“我不切！我是仲裁苹果。”\n");
        printf("🤝 众人决定：把它供在桌上，明天再议。\n");
    }
}

int main(void) {
    int 苹果 = 3, 人数 = 2;
    平分(苹果, 人数);
    return 0;
}

