#include <stdio.h>

int main(void) {
    int 工资 = 3000, 房租 = 3500, 期望剩余 = 800;
    int 实际剩余 = 工资 - 房租;
    printf("工资：%d 元\n", 工资);
    printf("房租：%d 元\n", 房租);
    printf("付完房租实际剩余：%d 元\n", 实际剩余);
    printf("期望剩余：%d 元\n", 期望剩余);
    if (实际剩余 >= 期望剩余) {
        printf("目标已达成，还多出 %d 元。\n", 实际剩余 - 期望剩余);
    } else {
        printf("距离目标还差 %d 元。\n", 期望剩余 - 实际剩余);
        printf("假设工资不变，房租需不高于 %d 元才能剩 %d 元。\n", 工资 - 期望剩余, 期望剩余);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int 苹果 = 3, 人数 = 2;
    double 每人 = (double)苹果 / 人数;
    printf("把 %d 个苹果平分给 %d 个人，每人得到 %.1f 个苹果。\n", 苹果, 人数, 每人);
    return 0;
}
